"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[51788],{3331:(e,r,n)=>{n.d(r,{R:()=>a,x:()=>o});var t=n(36672);const i={},s=t.createContext(i);function a(e){const r=t.useContext(s);return t.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function o(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),t.createElement(s.Provider,{value:r},e.children)}},68488:(e,r,n)=>{n.r(r),n.d(r,{assets:()=>l,contentTitle:()=>o,default:()=>m,frontMatter:()=>a,metadata:()=>t,toc:()=>d});const t=JSON.parse('{"id":"2023/04/02","title":"02","description":"Amazon Echo-enheder gemmer WiFi-adgangskoder i klar tekst, hvilket g\xf8r dem s\xe5rbare over for angreb med fysisk adgang","source":"@site/i18n/da/docusaurus-plugin-content-docs/current/2023/04/02.md","sourceDirName":"2023/04","slug":"/2023/04/02","permalink":"/da/2023/04/02","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/da/docusaurus-plugin-content-docs//current/2023/04/02.md","tags":[],"version":"current","frontMatter":{"localized_date":"2. april 2023","top_news":"Amazon Echo-enheder gemmer WiFi-adgangskoder i klar tekst, hvilket g\xf8r dem s\xe5rbare over for angreb med fysisk adgang"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-03","permalink":"/da/2023/04/03"},"next":{"title":"01","permalink":"/da/2023/04/01"}}');var i=n(23420),s=n(3331);const a={localized_date:"2. april 2023",top_news:"Amazon Echo-enheder gemmer WiFi-adgangskoder i klar tekst, hvilket g\xf8r dem s\xe5rbare over for angreb med fysisk adgang"},o=void 0,l={},d=[{value:"Amazon Echo-enheder gemmer WiFi-adgangskoder i klar tekst, hvilket g\xf8r dem s\xe5rbare over for angreb med fysisk adgang",id:"amazon-echo-enheder-gemmer-wifi-adgangskoder-i-klar-tekst-hvilket-g\xf8r-dem-s\xe5rbare-over-for-angreb-med-fysisk-adgang",level:2},{value:"Google Drive indf\xf8rer filgr\xe6nser og afsk\xe6rer potentielt betalende kunder",id:"google-drive-indf\xf8rer-filgr\xe6nser-og-afsk\xe6rer-potentielt-betalende-kunder",level:2},{value:"Vejledning til logiske klokkedesigns til p\xe5lidelig h\xe6ndelsesordination i distribuerede systemer",id:"vejledning-til-logiske-klokkedesigns-til-p\xe5lidelig-h\xe6ndelsesordination-i-distribuerede-systemer",level:2},{value:"Frankrigs 3034 km HexaTrek Trail er \xe5ben for gennemvandring",id:"frankrigs-3034-km-hexatrek-trail-er-\xe5ben-for-gennemvandring",level:2},{value:"Udvikler Raph Levien flytter fra Rust til C++",id:"udvikler-raph-levien-flytter-fra-rust-til-c",level:2},{value:"Kursuskammerat: Connecting Self-Learners Worldwide for Collaborative Online Learning",id:"kursuskammerat-connecting-self-learners-worldwide-for-collaborative-online-learning",level:2},{value:"Planter udsender lyde, n\xe5r de er stressede, hvilket \xe5bner nye d\xf8re for forst\xe5else",id:"planter-udsender-lyde-n\xe5r-de-er-stressede-hvilket-\xe5bner-nye-d\xf8re-for-forst\xe5else",level:2},{value:"Simulering af underjordisk BBS-system fra 1987: Chat, spil og e-mail",id:"simulering-af-underjordisk-bbs-system-fra-1987-chat-spil-og-e-mail",level:2},{value:"Google udskyder slukning af Manifest V2 for Chrome-udvidelser",id:"google-udskyder-slukning-af-manifest-v2-for-chrome-udvidelser",level:2},{value:"Wine 8.5: Forbedret vkd3d, WinRT-tema og fejlrettelser",id:"wine-85-forbedret-vkd3d-winrt-tema-og-fejlrettelser",level:2},{value:"Resume-First Hiring Process: Udnyttende og ineffektivt",id:"resume-first-hiring-process-udnyttende-og-ineffektivt",level:2},{value:"Eks-SpaceX-medarbejdere grundlagde snesevis af rumstartups og rejste 3,6 mia. dollars",id:"eks-spacex-medarbejdere-grundlagde-snesevis-af-rumstartups-og-rejste-36-mia-dollars",level:2},{value:"SpaceX&#39;s Starship flytter til opsendelsessted, l\xf8ft muligvis den 10. april",id:"spacexs-starship-flytter-til-opsendelsessted-l\xf8ft-muligvis-den-10-april",level:2},{value:"&#39;ccurl.sh&#39; g\xf8r det muligt for cURL at udnytte Chrome-cookies p\xe5 en overskuelig m\xe5de",id:"ccurlsh-g\xf8r-det-muligt-for-curl-at-udnytte-chrome-cookies-p\xe5-en-overskuelig-m\xe5de",level:2},{value:"MIT&#39;s Course on RNNs &amp; Transformers for Deep Learning",id:"mits-course-on-rnns--transformers-for-deep-learning",level:2}];function g(e){const r={a:"a",h2:"h2",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(r.h2,{id:"amazon-echo-enheder-gemmer-wifi-adgangskoder-i-klar-tekst-hvilket-g\xf8r-dem-s\xe5rbare-over-for-angreb-med-fysisk-adgang",children:"Amazon Echo-enheder gemmer WiFi-adgangskoder i klar tekst, hvilket g\xf8r dem s\xe5rbare over for angreb med fysisk adgang"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.strong,{children:"Alexa, hvad er min wifi-adgangskode?"}),"\nAmazon Echo-enheder gemmer WiFi-adgangskoder i klartekst, hvilket g\xf8r det muligt for angribere med fysisk adgang at udtr\xe6kke netv\xe6rksadgangskoder relativt let. Dette udg\xf8r en stor sikkerhedsrisiko for hoteller eller virksomheder, der bruger enhederne p\xe5 deres interne eller private tr\xe5dl\xf8se netv\xe6rk, da det giver angribere adgang til alt andet udstyr p\xe5 netv\xe6rket, hvilket potentielt kan v\xe6re en overtr\xe6delse af databeskyttelsesloven. Hashing af adgangskoder er en industristandard, og for en virksomhed, der har solgt sin hardware til millioner af mennesker, er det helt uacceptabelt ikke at kryptere disse data. Enheden krypterer ikke API-n\xf8glerne til Spotify zeroconf- og eSDK-API'er. Fysisk sikkerhed er afg\xf8rende, n\xe5r der designes indlejret hardware, og Amazon skal tage fat p\xe5 dette problem for at forhindre fremtidige sikkerhedsbrud.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35399590",children:"Discussion Service"}),", ",(0,i.jsx)(r.a,{href:"https://dragon863.github.io/blog/alexa.html",children:"Artikel"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"google-drive-indf\xf8rer-filgr\xe6nser-og-afsk\xe6rer-potentielt-betalende-kunder",children:"Google Drive indf\xf8rer filgr\xe6nser og afsk\xe6rer potentielt betalende kunder"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.strong,{children:"Google Drive foretager en overraskende udrulning af filgr\xe6nser, hvilket l\xe5ser nogle brugere ude."}),"\nGoogle Drive har indf\xf8rt en filbegr\xe6nsning uden varsel, hvilket potentielt kan afsk\xe6re betalende kunder, der er l\xe5st ude af nye filopladninger; Reddit-brugere har allerede klaget over dette problem i l\xf8bet af de sidste to m\xe5neder. Den pludselige indf\xf8relse af en filbegr\xe6nsning er ikke anf\xf8rt p\xe5 hverken Google One- eller Google Workspace-planens sider eller n\xe6vnt i supportdokumenter. Det har ogs\xe5 forhindret brugere i at udnytte den lagerplads, de har k\xf8bt, da begr\xe6nsningen forhindrer dem i at bruge pladsen. Google Drevs gr\xe6nse p\xe5 5 millioner filer anses hverken for acceptabel eller rimelig af mange brugere, da den ikke er dokumenteret nogen steder, og prisen for at bruge Google Workspaces lagerplan anses for at v\xe6re urimelig h\xf8j. Google h\xe6vder, at gr\xe6nsen er en sikkerhedsforanstaltning for at forhindre misbrug af systemet, som kan p\xe5virke stabiliteten og sikkerheden, men denne form for kundekommunikation anses for at v\xe6re d\xe5rlig.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35397071",children:"Discussion Service"}),", ",(0,i.jsx)(r.a,{href:"https://arstechnica.com/gadgets/2023/03/google-drive-does-a-surprise-rollout-of-file-limits-locking-out-some-users/",children:"Artikel"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"vejledning-til-logiske-klokkedesigns-til-p\xe5lidelig-h\xe6ndelsesordination-i-distribuerede-systemer",children:"Vejledning til logiske klokkedesigns til p\xe5lidelig h\xe6ndelsesordination i distribuerede systemer"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.strong,{children:"Clocks and Causality - Ordering Events in Distributed Systems (2022)."}),"\nLogiske ure er afg\xf8rende for at ordne begivenheder i distribuerede systemer, og Lamport- og vektorure er popul\xe6re designs. Lamport-ure giver stigende numre inden for en knude, mens vektorure sporer knude-id'er og respektive h\xe6ndelses-id'er med henblik p\xe5 samtidige h\xe6ndelsessammenligninger. Dotted Vector Clock og Vector Timestamps optimerer tidsstempelkontroller og muligg\xf8r h\xe6ndelsesordnering p\xe5 tv\xe6rs af knudepunkter. Versionsvektorer sporer dataversioner i lagerknuder med flere ledere. Lamport Causal Clock registrerer kausalitet, men kr\xe6ver mere plads og tidskompleksitet. Total Order kr\xe6ver sekventiel r\xe6kkef\xf8lge baseret p\xe5 tidsm\xe6ssige og kausale relationer. Logiske ure er afg\xf8rende i samarbejdsprogrammer for redigering. Azure Time Sync bruger PTP, mens AWS og Google Cloud bruger NTP. Artiklen g\xf8r opm\xe6rksom p\xe5 begr\xe6nsningerne ved at fors\xf8ge at betragte tid som absolut og fremh\xe6ver betydningen af begivenhedsordnering i banktransaktioner.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35399603",children:"Discussion Service"}),", ",(0,i.jsx)(r.a,{href:"https://www.exhypothesi.com/clocks-and-causality/",children:"Artikel"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"frankrigs-3034-km-hexatrek-trail-er-\xe5ben-for-gennemvandring",children:"Frankrigs 3034 km HexaTrek Trail er \xe5ben for gennemvandring"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.strong,{children:"Hexatrek: Den langdistancetur i Frankrig."}),"\nFrankrigs 3034 km lange HexaTrek-sti er nu \xe5ben for gennemvandring og forbinder 14 nationalparker og krydser Rum\xe6niens Via Transilvanica-sti.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35397051",children:"Discussion Service"}),", ",(0,i.jsx)(r.a,{href:"https://en.hexatrek.com",children:"Artikel"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"udvikler-raph-levien-flytter-fra-rust-til-c",children:"Udvikler Raph Levien flytter fra Rust til C++"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.strong,{children:"Overgang fra Rust til C++."}),"\nUdvikleren Raph Levien meddeler beslutningen om at flytte fra Rust til C++ p\xe5 grund af begr\xe6nsninger i f\xf8rstn\xe6vnte, s\xe5som manglende valgmuligheder i buildsystemet og langsomme innovationsfremskridt p\xe5 trods af sikkerhedsgarantierne. Levien mener, at han kan undg\xe5 sikkerhedsproblemer, og at fejl vedr\xf8rende hukommelsessikkerhed ikke er v\xe6sentligt mere skadelige end andre fejl, og at C++ udvikler sig hurtigt til at blive mere sikkert. Levien understreger vigtigheden af f\xe6llesskabet og giver udtryk for bekymring over diskriminationspolitikker og tilsyneladende anmassende dominerende Rust-fork\xe6mpere. Artiklen er dog satirisk, og nogle l\xe6sere udtrykker interesse for C++ frem for Rust.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35400047",children:"Discussion Service"}),", ",(0,i.jsx)(r.a,{href:"https://raphlinus.github.io/rust/2023/04/01/rust-to-cpp.html",children:"Artikel"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"kursuskammerat-connecting-self-learners-worldwide-for-collaborative-online-learning",children:"Kursuskammerat: Connecting Self-Learners Worldwide for Collaborative Online Learning"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.strong,{children:"Vis Coursemate - forbind med andre selvl\xe6rende."}),"\nCoursemate er en platform, hvor selvl\xe6rere kan oprette forbindelse og samarbejde om onlinekurser med ligesindede i deres eget land eller i hele verden. Platformen kan integreres med brugernes foretrukne online-kurser og tager mindre end et minut at oprette. Nogle brugere foresl\xe5r, at Coursemate kunne have gavn af mere specifikke l\xe6ringsm\xe5l ud over det nuv\xe6rende fokus p\xe5 frontend- og backend-emner. Derudover vil brugerne gerne se flere eksempler p\xe5 f\xe6llesskaber og mentorordninger. Nogle brugere foresl\xe5r ogs\xe5, at man udvider filtrering efter alder og land til at tillade filtrering efter interesse. P\xe5 trods af visse kritikpunkter er webstedet veludf\xf8rt og overskueligt. Nogle brugere udtrykker et \xf8nske om en platform til at komme i kontakt med eksperter, der kan hj\xe6lpe med at forklare specifikt kursusindhold.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35398480",children:"Discussion Service"}),", ",(0,i.jsx)(r.a,{href:"https://www.coursem8.com/",children:"Artikel"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"planter-udsender-lyde-n\xe5r-de-er-stressede-hvilket-\xe5bner-nye-d\xf8re-for-forst\xe5else",children:"Planter udsender lyde, n\xe5r de er stressede, hvilket \xe5bner nye d\xf8re for forst\xe5else"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.strong,{children:"Lyde, der udsendes af planter under stress, er luftb\xe5rne og informative."}),"\nPlanter kan udsende informative luftb\xe5rne lyde, n\xe5r de er under stress, hvilket \xe5bner nye muligheder for at forst\xe5 deres interaktioner med milj\xf8et. Dette nye felt af plantebioakustik introducerede potentialet for akustisk kommunikation af planter, som kan detekteres af maskinl\xe6ringsmodeller og kan p\xe5virke landbruget ud over traditionelle signaler.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35396156",children:"Discussion Service"}),", ",(0,i.jsx)(r.a,{href:"https://www.cell.com/cell/fulltext/S0092-8674(23)00262-3",children:"Artikel"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"simulering-af-underjordisk-bbs-system-fra-1987-chat-spil-og-e-mail",children:"Simulering af underjordisk BBS-system fra 1987: Chat, spil og e-mail"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.strong,{children:"ChatGPT simulerer BBS-system fra 1987."}),"\nArtiklen omhandler simulering af et BBS-system fra 1987, herunder chat, spil og e-mail. Brugere kan oprette en konto, l\xe6se nyheder og dokumentation, se tekstfiler og kommunikere med andre brugere. Castle Quest, et tekstbaseret spil, kan spilles p\xe5 systemet. ShareGPT g\xf8r det muligt at dele kodestumper i samtaler. Den historiske n\xf8jagtighed af ChatGPT's output er tvivlsom, men interessant. En bruger foresl\xe5r at simulere en BBS fra 1987 med yderligere funktioner. Artiklen giver et nostalgisk indblik i fortidens teknologi.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35396165",children:"Discussion Service"}),", ",(0,i.jsx)(r.a,{href:"https://sharegpt.com/c/ICZsSl7",children:"Artikel"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"google-udskyder-slukning-af-manifest-v2-for-chrome-udvidelser",children:"Google udskyder slukning af Manifest V2 for Chrome-udvidelser"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.strong,{children:"P\xe5skudte \xe6ndringer i udfasningen af Manifest V2."}),"\nGoogle har udskudt alle eksperimenter i januar med at slukke for Manifest V2 i pre-release-kanaler af Chrome og \xe6ndringer af det fremh\xe6vede badge i Chrome Webstore, og vil evaluere alle efterf\xf8lgende milep\xe6le. Udviklerne vil f\xe5 tilstr\xe6kkelig tid til at opdatere og teste deres udvidelser efter lanceringen af disse nye funktioner, inden Manifest V2 sl\xe5s fra. Googles forpligtelse til at udrulle Manifest V3 forventes at forbedre sikkerheden, privatlivets fred og ydeevnen for deres brugere. Der var tilbagemeldinger fra udviklerf\xe6llesskabet om vanskelighederne ved at bruge Manifest V3, og nogle af disse er blevet l\xf8st, men der er stadig forbedringer, der skal foretages, og Google er fortsat engageret i overgangen.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35402698",children:"Discussion Service"}),", ",(0,i.jsx)(r.a,{href:"https://groups.google.com/a/chromium.org/g/chromium-extensions/c/zQ77HkGmK9E/m/HjaaCIG-BQAJ",children:"Artikel"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"wine-85-forbedret-vkd3d-winrt-tema-og-fejlrettelser",children:"Wine 8.5: Forbedret vkd3d, WinRT-tema og fejlrettelser"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.strong,{children:"Wine 8.5."}),"\nWine-udgave 8.5 kommer med forbedret vkd3d, WinRT-tema og fejlrettelser, herunder bedre fejlrapportering i IDL-kompileren, underst\xf8ttelse af UIA_IsOffscreenPropertyId til MSAA-udbydere og fuld initialisering af i386 FPU-kontekst p\xe5 ARM64. Bin\xe6re pakker er tilg\xe6ngelige for forskellige distributioner, og kildekoden er tilg\xe6ngelig direkte fra git-repositoriet. Fejlrettelser omfatter mscoree, imm32 og LDAP bind.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35398643",children:"Discussion Service"}),", ",(0,i.jsx)(r.a,{href:"https://www.winehq.org/announce/8.5",children:"Artikel"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"resume-first-hiring-process-udnyttende-og-ineffektivt",children:"Resume-First Hiring Process: Udnyttende og ineffektivt"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.strong,{children:"Den, der indsender et CV, har allerede tabt."}),"\nDen traditionelle ans\xe6ttelsesproces, hvor CV'et kommer f\xf8rst, er udnyttende og i sidste ende ineffektiv, idet arbejdsgiverne hovedsagelig bruger den til at spare tid og reducere omkostningerne p\xe5 ans\xf8gerens bekostning. Man kan se bort fra CV'er, og personlige anbefalinger og netv\xe6rk er mere effektive metoder til at sikre sig et job og omg\xe5 den mangelfulde og uretf\xe6rdige proces. Akademisk ans\xe6ttelse er utroligt demoraliserende, og nepotisme kan skabe etiske problemer. Jobs\xf8gende m\xe5 g\xf8re, hvad de kan, for at omg\xe5 systemet, men det er stadig n\xf8dvendigt at tage CV'er alvorligt. Indl\xe6gget tilbyder v\xe6rkt\xf8jer til jobs\xf8gere, s\xe5 de kan skille sig ud, herunder at skrive et f\xf8lgebrev eller bruge et AI-v\xe6rkt\xf8j til at skrive det p\xe5 to minutter.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35397271",children:"Discussion Service"}),", ",(0,i.jsx)(r.a,{href:"https://www.residentcontrarian.com/p/he-who-submits-a-resume-has-already",children:"Artikel"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"eks-spacex-medarbejdere-grundlagde-snesevis-af-rumstartups-og-rejste-36-mia-dollars",children:"Eks-SpaceX-medarbejdere grundlagde snesevis af rumstartups og rejste 3,6 mia. dollars"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.strong,{children:"SpaceX-alumener forgrener sig ud og former startup-\xf8konomien."}),"\nTidligere SpaceX-ansatte har grundlagt snesevis af rumstartups og rejst 3,6 mia. dollars for at fremme innovation inden for navigation i lavt kredsl\xf8b og levering af nyttelasttjenester. Medstifterne nyder godt af det f\xe6llesskab og den h\xf8jrisikotolerance, der blev etableret hos SpaceX, og opsendelsestjenesterne hj\xe6lper ogs\xe5 med at fremsende teknologiske prototyper, maskiner og navigationssatellitter. Software-as-a-service-industrien vokser og betjener det nystartede \xf8kosystem i rumfart. NASA og Boeing kunne drage fordel af at fremme en startup-kultur, da \xe6ldre kode og ufuldst\xe6ndig kode holder de etablerede virksomheder tilbage. Muligheder inden for rumforskning giver likviditet p\xe5 markedet, og investorer modtager millioner for risikable m\xe5neskud. Nogle kommentarer antyder, at artiklen f\xf8les som en pressemeddelelse.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35404823",children:"Discussion Service"}),", ",(0,i.jsx)(r.a,{href:"https://interactive.satellitetoday.com/via/april-2023/how-spacex-alums-are-branching-out-and-shaping-the-startup-economy/",children:"Artikel"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"spacexs-starship-flytter-til-opsendelsessted-l\xf8ft-muligvis-den-10-april",children:"SpaceX's Starship flytter til opsendelsessted, l\xf8ft muligvis den 10. april"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.strong,{children:"SpaceX flytter Starship til opsendelsesstedet, og der kan kun v\xe6re f\xe5 dage til at l\xf8fte op."}),"\nSpaceX har flyttet sit Starship til et opsendelsessted i det sydlige Texas, som kan v\xe6re klar til at lette allerede den 10. april, hvis FAA-tilladelsen gives. Den gigantiske, Super Heavy-raket skal tjene NASA som en m\xe5nelandingsfart\xf8j til Artemis-missionerne p\xe5 m\xe5nen. SpaceX har investeret over 1 mia. USD i sit opsendelses- og fangst\xe5rn til st\xf8tte for Starship og Super Heavy, som selskabet har v\xe6ret mere forsigtigt med at udvikle p\xe5 sit anl\xe6g i South Texas. Hvis det lykkes, kan dette g\xf8re lavt kredsl\xf8b om jorden mere let tilg\xe6ngeligt for fagfolk.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35405030",children:"Discussion Service"}),", ",(0,i.jsx)(r.a,{href:"https://arstechnica.com/science/2023/04/spacex-moves-starship-to-launch-site-and-liftoff-could-be-just-days-away/",children:"Artikel"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"ccurlsh-g\xf8r-det-muligt-for-curl-at-udnytte-chrome-cookies-p\xe5-en-overskuelig-m\xe5de",children:"'ccurl.sh' g\xf8r det muligt for cURL at udnytte Chrome-cookies p\xe5 en overskuelig m\xe5de"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.strong,{children:"Vis Brug cookies fra Chrome (CDP) i cURL uden at kopiere og inds\xe6tte."}),'\n\'ccurl.sh\' er et bash-script, der g\xf8r det muligt for cURL at bruge Chrome-cookies uden brug af et GUI-v\xe6rkt\xf8j som Postman, idet det bruger Chrome DevTools-protokollen til at dumpe cookies fra en specifik fane i den lokale Chrome-instans i overskriften p\xe5 en cURL-kommando og undg\xe5r cookiel\xe6kage i shell-historikfilen; scriptet kr\xe6ver bash, websocat og jq for at kunne k\xf8re, og en fane med de cookies, der skal bruges, skal \xe5bnes i Chrome, som skal startes med "google-chrome-stable --remote-debugging-port=9222", og kan installeres ved at kopiere scriptet til "/usr/bin/ccurl" og g\xf8re det eksekverbart.\n',(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35399218",children:"Discussion Service"}),", ",(0,i.jsx)(r.a,{href:"https://github.com/fipso/ccurl.sh",children:"Artikel"}),"."]}),"\n",(0,i.jsx)(r.h2,{id:"mits-course-on-rnns--transformers-for-deep-learning",children:"MIT's Course on RNNs & Transformers for Deep Learning"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.strong,{children:"MIT 6.S191: Recurrent Neural Networks, Transformers, and Attention."}),"\nMIT's 6.S191-kursus d\xe6kker recurrent neural networks (RNNs), transformers og opm\xe6rksomhed til deep learning, som vist p\xe5 YouTube. Kommentarerne til videoen sp\xe6nder fra sp\xf8rgsm\xe5lstegn ved konventionerne for navngivning af parametre til anmodninger om anbefalinger om, hvor man kan l\xe6re neurale netv\xe6rk og grundl\xe6ggende viden om dybdeindl\xe6ring. Kursets brug af TensorFlow og upload af videoerne til de enkelte medarbejderes YouTube-kanaler diskuteres ogs\xe5.\n",(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35405338",children:"Discussion Service"}),", ",(0,i.jsx)(r.a,{href:"https://www.youtube.com/watch?v=ySEx_Bqxvvo",children:"Artikel"}),"."]})]})}function m(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,i.jsx)(r,{...e,children:(0,i.jsx)(g,{...e})}):g(e)}}}]);